//! 🧪️ Original decoder grants govern record-intermediate retirement before native publication.
use super::*;
use semio_framework_value::native_decoding::{NativeDecodeRetirementRecipient,NativeDecodeAllocation};
use semio_framework_dsl_record::{RecordSpec,RecordLayout,FieldSpec,Shape,FieldValue,NativeSchemaControl};
fn ordinary()->RecordSpec{RecordSpec::new(None,RecordLayout::Lines,vec![FieldSpec::new(1,"value",Shape::Text)])}
fn schema<C:NativeSchemaControl>(native:&mut C)->Result<RecordSpec,ValueError>{let mut fields=native.allocate_vec(1)?;fields.push(semio_framework_dsl_record::producer::field(1,"value",Shape::Text,native)?);semio_framework_dsl_record::producer::record(None,RecordLayout::Lines,fields,native)}
fn decode_schema(native:&mut NativeDecodeControl<'_>)->Result<RecordSpec,ValueError>{schema(native)}
fn encode_schema(native:&mut semio_framework_value::NativeEncodeControl<'_>)->Result<RecordSpec,ValueError>{schema(native)}
#[test]
fn original_record_decoder_returns_refused_retirement_and_preserves_the_native_oracle(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🚪️control/🔣️.json")).unwrap();let payload=crate::io_schema::IoPayload::Text(law["nativeLiteral"].as_str().unwrap().to_owned());let literal=law["literal"].as_str().unwrap();
 for row in law["cases"].as_array().unwrap(){let mut grant:semio_framework_value::RetainedCloneGrant=serde_json::from_value(law["grant"].clone()).unwrap();grant.maximum_release_bytes=row["release"].as_u64().unwrap()as usize;let mut recipient=NativeDecodeRetirementRecipient::new();let ledger=std::sync::atomic::AtomicUsize::new(0);let mut allocation=|request:NativeDecodeAllocation|{assert_eq!(request.owned_bytes,ledger.load(std::sync::atomic::Ordering::Relaxed));ledger.store(request.next_owned_bytes,std::sync::atomic::Ordering::Relaxed);Ok(())};let mut progress=|_|true;let mut native=NativeDecodeControl::new_forwarded(law["nativeBytes"].as_u64().unwrap()as usize,&mut progress,&mut allocation);native.install_retirement_recipient(&mut recipient).unwrap();let mut progress=|_|true;let mut sql=SqliteSnapshotControl::new(&mut progress,crate::sqlite_snapshot::SqliteDatabaseLimits::default());let spec=RecordSpecProducer{ordinary,decoding:decode_schema,encoding:encode_schema};
 let result=decode_sqlite_snapshot_record_native(&payload,law["envelope"].as_str().unwrap(),spec,|record, snapshot_output, native,_body| { let constructed: Result<_, semio_framework_value::ValueError> = (|| {match record.fields.get(&1){Some(FieldValue::Text(text))=>native.copy_text(text),_=>Err(ValueError::literal(ValueRefusalKind::InvalidValue,"original record fixture text differs"))}})(); *snapshot_output = Some(constructed?); Ok(()) },&mut sql,&mut crate::os_store::NativeSnapshotDecodeOwner::new(&mut native,grant));assert_eq!(result.is_ok(),row["accepted"].as_bool().unwrap());if let Ok(text)=result{assert_eq!(serde_json::to_value(text).unwrap(),serde_json::to_value(literal).unwrap());assert!(!native.has_retirement_owner());}else{assert!(native.has_retirement_owner());let full:semio_framework_value::RetainedCloneGrant=serde_json::from_value(law["grant"].clone()).unwrap();while native.has_retirement_owner(){native.close_retirement_recipient(full).unwrap();assert_eq!(native.owned_bytes(),ledger.load(std::sync::atomic::Ordering::Relaxed));}}drop(native);assert!(!recipient.has_owner());println!("[DEBUG] Original record decoder {} independentSerde=true originalGrant=true originalRecipient=true samePhysicalPortDrain=true",row["id"]);}
}
